CREATE TABLE IF NOT EXISTS players (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS fixtures (id INTEGER PRIMARY KEY AUTOINCREMENT, starts_at TEXT NOT NULL UNIQUE, materialized_at TEXT NOT NULL, finalized_at TEXT);
CREATE TABLE IF NOT EXISTS availability (fixture_id INTEGER NOT NULL REFERENCES fixtures(id), player_id INTEGER NOT NULL REFERENCES players(id), keen INTEGER NOT NULL DEFAULT 0, UNIQUE(fixture_id, player_id));
CREATE TABLE IF NOT EXISTS lineup (fixture_id INTEGER NOT NULL REFERENCES fixtures(id), player_id INTEGER NOT NULL REFERENCES players(id), role TEXT NOT NULL CHECK(role IN ('selected','reserve')), position INTEGER NOT NULL, UNIQUE(fixture_id, player_id));
